# target events are events with v==target
target_idxs = set(i for i,(u,v,t) in enumerate(ew) if v==target)
print('target event indices:', target_idxs)
# BFS from each start event through nexts to see if any path reaches a target event
from collections import deque
found = False
found_path = None
for s in start_idxs:
    q = deque([[s]])
    visited = set([s])
